         // null out this channel, so it'll stop trying to run the url.
         *aRetVal = nullptr;
         rv = NS_OK;
-      } else {
-        // Got IMAP folder URL from command line (most likely).
-        // Set action to nsImapSelectFolder (x-application-imapfolder), so
